from qiskit import QuantumCircuit

def build():
    qc = QuantumCircuit(6)
    pairs = [(0, 1, "01"), (2, 3, "10"), (4, 5, "11")]

    for first, second, _ in pairs:
        qc.h(first)
        qc.cx(first, second)

    # Encode each (b1, b0) so decoding yields b1 on `first`, b0 on `second`.
    for first, _, bits in pairs:
        b1, b0 = bits
        if b0 == "1":
            qc.x(first)
        if b1 == "1":
            qc.z(first)

    for first, second, _ in pairs:
        qc.cx(first, second)
        qc.h(first)

    return qc
```

